function localizeZhNames(s) {
    if (!s) return s;
    let out = String(s);
    for (const [a, b] of ZH_NAMES) if (out.indexOf(a) >= 0) out = out.split(a).join(b);
    return out;
}
function localizeZhPlaces(s) {
    if (!s) return s;
    let out = String(s);
    for (const [a, b] of ZH_PLACES) if (out.indexOf(a) >= 0) out = out.split(a).join(b);
    return out;
}
function localizeZhProper(s, force) {
    if ((!force && GS.lang !== 'zh') || !s) return s;
    if (ZH_KEEP.has(s)) return s;
    let out = localizeZhPlaces(localizeZhTerms(localizeZhNames(String(s))));
    // Remove spaces introduced between two Chinese characters by Latin place replacement.
    for (let i = 0; i < 3; i++) out = out.replace(/([\u4e00-\u9fff])\s+([\u4e00-\u9fff])/g, '$1$2');
    return out;
}
const L = (o) => nameReplace(localizeZhProper((o && (o[GS.lang] !== undefined ? o[GS.lang] : o.en)) || ''));
const esc = (s) => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const fmt = (s) => esc(s).replace(/\n/g, '<br>');
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));

function toast(msg, kind) {
    const root = $('#toast-root');
    if (!root) return;
    const d = document.createElement('div');
    d.className = 'toast ' + (kind || '');
    d.textContent = msg;
    root.appendChild(d);
    setTimeout(() => d.classList.add('show'), 20);
    setTimeout(() => { d.classList.remove('show'); setTimeout(() => d.remove(), 400); }, 3600);
}

function closeModal() {
    const root = $('#modal-root');
    if (root) root.innerHTML = '';
}

function openModal(html, opts) {
    opts = opts || {};
    const root = $('#modal-root');
    if (!root) return;
    root.innerHTML = '';
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay ' + (opts.className || '');
    const box = document.createElement('div');
    box.className = 'modal-box ' + (opts.boxClass || '');
    box.innerHTML = html;
    if (opts.buttons && opts.buttons.length) {
        const row = document.createElement('div');
        row.className = 'modal-btns';
        opts.buttons.forEach((b) => {
            const btn = document.createElement('button');
            btn.className = 'btn ' + (b.cls || '');
            btn.textContent = b.label;
            btn.onclick = () => { if (b.onClick) b.onClick(); else closeModal(); };
            row.appendChild(btn);
        });
        box.appendChild(row);
    }
    overlay.appendChild(box);
    root.appendChild(overlay);
    return box;
}

function showNote(text, title) {
    const root = $('#note-root');
    if (!root) return;
    root.innerHTML = '';
    const n = document.createElement('div');
    n.className = 'note-popup';
    n.innerHTML =
        '<div class="note-pin">📌</div>' +
        '<div class="note-head">' + fmt(title || T[GS.lang].noteTitle) + '</div>' +
        '<div class="note-body">' + fmt(text) + '</div>' +
        '<button class="note-close" aria-label="close">×</button>';
    n.querySelector('.note-close').onclick = () => n.remove();
    root.appendChild(n);
}

