// Ensure UI strings follow the same Latin-script proper-name rule.
(function localizeTZhStrings() {
    const walk = (v) => {
        if (typeof v === 'string') return localizeZhProper(v, true);
        if (Array.isArray(v)) return v.map(walk);
        if (v && typeof v === 'object') { Object.keys(v).forEach((k) => { v[k] = walk(v[k]); }); return v; }
        return v;
    };
    walk(T.zh);
})();

