            from: 'Travel & Mobility',
            email: 'travel@axiom-dynamics.com',
            sub: { en: 'Ticket issued — TGV Lyria 9215 — Wednesday 10 February, 07:34', zh: '车票已出票——TGV Lyria 9215——2 月 10 日（周三）07:34' },
