// Avatar file names used by the contact/avatar renderer (assets/avatars/<file>.webp).
// 48_contactsync.js keeps its own map; Sync owner: merge this map (adds senja, alan).
const CONTACT_AVATAR_FILES = {
    zoe: 'zoe', claire: 'claire', alex: 'alex', mom: 'mom', priya: 'priya', dana: 'dana',
    jean: 'jean', ines: 'ines', max: 'max', julia: 'julia', klara: 'klara', nadia: 'nadia',
    nadine: 'nadine', chen: 'chen', anke: 'anke', karen: 'karen', pumpkin: 'pumpkin',
    sven: 'sven', senja: 'senja', alan: 'alan'
};

function contactById(id) {
    for (let i = 0; i < CONTACTS.length; i++) if (CONTACTS[i].id === id) return CONTACTS[i];
    return null;
}
function contactMet(c) {
    if (!c) return false;
    if (typeof c.met !== 'function') return true;
    try { return !!c.met(); } catch (e) { return false; }
}
function contactBase(c) {
    if (!c) return 50;
    return typeof c.baseAffinity === 'number' ? c.baseAffinity : 50;
}
function contactRelation(c) {
    if (!c) return { en: 'Occupation', zh: '职业' };
    return c.occupation || { en: '—', zh: '—' };
}
function contactStatusLine(c) {
    if (!c || typeof c.stance !== 'function') return null;
    try { return c.stance(); } catch (e) { return null; }
}
function affinityOf(id) {
    const c = contactById(id);
    if (!c) return 50;
    if (GS.affinity[id] == null) GS.affinity[id] = contactBase(c);
    return GS.affinity[id];
}
function contactMatchesMail(c, m) {
    if (!c || !m) return false;
    const hay = (String(m.from || '') + ' ' + String(m.email || '')).toLowerCase();
    const aliases = c.aliases || [];
    for (let i = 0; i < aliases.length; i++) {
        if (hay.indexOf(String(aliases[i]).toLowerCase()) >= 0) return true;
    }
    return false;
}

