function contactThreads(id) {
    if (!GS.contactThreads[id]) GS.contactThreads[id] = [];
    return GS.contactThreads[id];
}
function repliedThisChapter(id) {
    const th = GS.contactThreads[id] || [];
    for (let i = 0; i < th.length; i++) {
        if (th[i].ch === GS.ch && th[i].from === 'you') return true;
    }
    return false;
}

