function fileById(id) {
    for (let i = 0; i < FILES_DATA.length; i++) if (FILES_DATA[i].id === id) return FILES_DATA[i];
    return null;
}
function fileCatLabel(cat) {
    const cats = AT('categories') || {};
    return cats[cat] || cat;
}

// ============================================================================
// HELPERS — runtime-safe access to engine functions defined later
// ============================================================================
function appL(x) {
    if (typeof L === 'function') return L(x);
    return x && (x[GS.lang] || x.en) || '';
}
function appSafe(fn, fallback) {
    try { return fn(); } catch (e) { return fallback; }
}
function appDate(d) {
    if (!d) return '';
    if (typeof fmtMailDate === 'function') return fmtMailDate(d);
    return String(d);
}
function appPlay(kind) {
    if (typeof playSfx === 'function') { try { playSfx(kind); } catch (e) { } }
}
function appToast(msg, kind) {
    if (typeof toast === 'function') toast(msg, kind || '');
}
function appVisibleMails() {
    if (typeof visibleMails !== 'function') return [];
    return appSafe(() => visibleMails(), []);
}
function appVisibleSyncs() {
    if (typeof visibleSyncs !== 'function') return [];
    return appSafe(() => visibleSyncs(), []);
}
function appSyncRevealed(s) {
    if (typeof isSyncRevealed !== 'function') return true;
    return appSafe(() => isSyncRevealed(s), true);
}
function appAllChapters() {
    if (typeof CH_DATA !== 'undefined' && Array.isArray(CH_DATA)) return CH_DATA;
    return [];
}
function appJournalText(entry) {
    if (!entry) return '';
    if (typeof journalText === 'function') {
        const t = appSafe(() => journalText(entry.key, entry.custom), null);
        if (t) return t;
    }
    return entry.key || '';
}
function appNowLabel() {
    if (GS.lang === 'zh') return GS.ch + ' 章';
    return 'Ch. ' + GS.ch;
}
// ---------------------------------------------------------------- scroll helpers
function appsScrollKey(el, root) {
    const tag = el.tagName || 'DIV';
    let cls = '';
    if (typeof el.className === 'string') {
        cls = el.className.split(/\s+/).filter(Boolean).slice(0, 2).join('.');
    }
    const sel = tag + (cls ? '.' + cls : '');
    let idx = 0;
    try {
        const all = root.querySelectorAll(sel);
        for (let i = 0; i < all.length; i++) { if (all[i] === el) { idx = i; break; } }
    } catch (e) { idx = 0; }
    return sel + '#' + idx;
}
function appsScrollCapture(root) {
    const out = [];
    if (!root || !root.querySelectorAll) return out;
    const els = root.querySelectorAll('*');
    for (let i = 0; i < els.length; i++) {
        const el = els[i];
        if ((el.scrollTop || 0) > 0 || (el.scrollLeft || 0) > 0) {
            out.push({ key: appsScrollKey(el, root), top: el.scrollTop || 0, left: el.scrollLeft || 0 });
        }
    }
    return out;
}
function appsScrollRestore(root, snap) {
    if (!root || !snap || !snap.length || !root.querySelectorAll) return;
    for (let i = 0; i < snap.length; i++) {
        const r = snap[i];
        const hash = r.key.lastIndexOf('#');
        if (hash < 0) continue;
        const sel = r.key.slice(0, hash);
        const idx = parseInt(r.key.slice(hash + 1), 10) || 0;
        try {
            const els = root.querySelectorAll(sel);
            const el = els[idx];
            if (el) { el.scrollTop = r.top; el.scrollLeft = r.left; }
        } catch (e) { /* selector may vanish */ }
    }
}
function appsWithScroll(rootSelector, fn) {
    const root = $(rootSelector);
    const snap = root ? appsScrollCapture(root) : [];
    const result = fn ? fn() : null;
    const root2 = $(rootSelector);
    if (root2) appsScrollRestore(root2, snap);
    return result;
}

// ============================================================================
// CONTACTS — read-only dossier app
// ============================================================================
function ensureContactState() {
    if (!(GS.contactSeen instanceof Set)) GS.contactSeen = new Set();
    if (GS._csLastCh == null) GS._csLastCh = GS.ch;
    if (GS.ch < GS._csLastCh) GS.contactSeen = new Set();
    // new game / restart rewrites GS.seenMails to a fresh Set in resetStoryState
    if (GS._csSeenMailsRef !== GS.seenMails) {
        if (GS._csSeenMailsRef !== undefined) GS.contactSeen = new Set();
        GS._csSeenMailsRef = GS.seenMails;
    }
    GS._csLastCh = GS.ch;
}
function contactSeenSet() {
    ensureContactState();
    return GS.contactSeen;
}
function markContactSeen(id) {
    ensureContactState();
    if (id) GS.contactSeen.add(id);
}
function contactIsSeen(id) {
    ensureContactState();
    return GS.contactSeen.has(id);
}
function contactIsNew(c) {
    if (!c || !contactMet(c)) return false;
    return !contactIsSeen(c.id);
}
function contactUnreadCount() {
    ensureContactState();
    let n = 0;
    for (let i = 0; i < CONTACTS.length; i++) {
        const c = CONTACTS[i];
        if (contactMet(c) && !GS.contactSeen.has(c.id)) n++;
    }
    return n;
}
function metContactList() {
    return CONTACTS.filter((c) => contactMet(c));
}
function selectContact(id) {
    const c = contactById(id);
    if (!c || !contactMet(c)) return;
    GS.selContact = id;
    markContactSeen(id);
    renderContacts();
    if (typeof updateUI === 'function') appSafe(() => updateUI(), null);
}
function contactRoleLine(c) {
    return appL(c.title || c.role);
}
function contactHasMessageButton(c) {
    if (!c || c.type === 'ai' || c.noChat) return false;
    const entry = chatEntryFor(c.id);
    if (!entry) return false;
    return !repliedThisChapter(c.id);
}
function groupRows(list) {
    return list.map((c) => {
            const active = GS.selContact === c.id ? ' active' : '';
            const isNew = contactIsNew(c);
            const canMsg = contactHasMessageButton(c);
            const msgTitle = canMsg ? AT('message') : AT('noNewMessages');
            return '<div class="ct-row' + active + (isNew ? ' is-new' : '') +
            '" onclick="selectContact(\'' + esc(c.id) + '\')">' +
            avatarHtml(c.name.en, 'avatar-sm') +
            '<div class="ct-row-main"><div class="ct-row-name">' + esc(appL(c.name)) +
            (c.type === 'ai' ? '<span class="ct-model-badge">' + (GS.lang === 'zh' ? '模型' : 'MODEL') + '</span>' : '') + '</div>' +
            '<div class="ct-row-role">' + esc(contactRoleLine(c)) + '</div></div>' +
            (isNew ? '<span class="ct-new-dot"></span>' : '') +
            '<button class="ct-row-msg' + (canMsg ? ' ready' : '') + '" title="' + esc(msgTitle) + '" ' +
            (canMsg ? '' : 'disabled ') +
            'onclick="event.stopPropagation();openContactSync(\'' + esc(c.id) + '\')">' + esc(GS.lang === 'zh' ? '发消息' : 'Message') + '</button>' +
            '</div>';
        }).join('');
}
function contactMailHistory(c) {
    const out = [];
    const chapters = appAllChapters();
    for (let ci = 0; ci < chapters.length; ci++) {
        const ch = chapters[ci];
        if (!ch || !ch.mails) continue;
        for (let i = 0; i < ch.mails.length; i++) {
            const m = ch.mails[i];
            if (!GS.seenMails.has(m.id)) continue;
            if (!contactMatchesMail(c, m)) continue;
            out.push({
                    chapter: ci,
                    date: (typeof mailDisplayDate === 'function' ? appSafe(() => mailDisplayDate(m), m.date) : (m._recvDate || m.date || '')),
                    time: (typeof mailDisplayTime === 'function' ? appSafe(() => mailDisplayTime(m), m.time) : (m._recvTime || m.time || '')),
                    subject: appL(m.sub),
                    from: m.from
                });
        }
    }
    out.sort((a, b) => {
            const ka = (a.date || '') + ' ' + (a.time || '');
            const kb = (b.date || '') + ' ' + (b.time || '');
            return ka < kb ? 1 : -1;
        });
    return out;
}
function contactSyncHistory(c) {
    const out = [];
    const syncs = appVisibleSyncs();
    for (let i = 0; i < syncs.length; i++) {
        const s = syncs[i];
        if (s.self) continue;
        if (!contactMatchesMail(c, { from: s.s, email: '' })) continue;
        if (!appSyncRevealed(s)) continue;
        out.push({ chapter: GS.ch, text: appL(s.t) });
    }
    return out;
}
function contactThreadLines(c) {
    return GS.contactThreads[c.id] || [];
}
function mailHistoryHtml(c) {
    const rows = contactMailHistory(c);
    if (!rows.length) return '';
    return rows.slice(0, 12).map((r) =>
        '<div class="ct-hist-row">' +
        '<span class="ct-hist-ch">' + (GS.lang === 'zh' ? '第' + r.chapter + '章' : 'Ch.' + r.chapter) + '</span>' +
        '<span class="ct-hist-date">' + esc(appDate(r.date)) + '</span>' +
        '<span class="ct-hist-subject">' + esc(r.subject) + '</span>' +
        '</div>').join('') +
    (rows.length > 12 ? '<div class="ct-empty">+' + (rows.length - 12) + '</div>' : '');
}
function syncHistoryHtml(c) {
    const rows = contactSyncHistory(c);
    if (!rows.length) return '';
    return rows.slice(0, 6).map((r) =>
        '<div class="ct-sync-row"><span class="ct-sync-ch">Sync</span>' +
        '<span class="ct-sync-text">' + esc(r.text.length > 120 ? r.text.slice(0, 118) + '…' : r.text) + '</span></div>'
    ).join('');
}
function threadHtml(c) {
    const lines = contactThreadLines(c);
    if (!lines.length) return '';
    return lines.slice(-8).map((l) =>
        '<div class="ct-thread-line ' + (l.from === 'you' ? 'you' : 'them') + '">' +
        '<span class="ct-thread-ch">' + (GS.lang === 'zh' ? '第' + l.ch + '章' : 'Ch.' + l.ch) + '</span>' +
        '<span class="ct-thread-body">' + esc(appL(l.text)) + '</span></div>'
    ).join('');
}
function journalHistoryHtml() {
    const entries = GS.journalEntries || [];
    if (!entries.length) return '';
    return entries.slice(-5).map((e) => {
            const txt = appJournalText(e);
            if (!txt) return '';
            return '<div class="ct-journal-row">' + esc(txt) + '</div>';
        }).join('') || '<div class="ct-empty">' + esc(AT('noHistory')) + '</div>';
}
function contactMessageBlock(c) {
    ensureContactState();
    if (c.type === 'ai') return '<div class="ct-chat-block"><div class="ct-chat-note">' + esc(AT('modelNoChat')) + '</div></div>';
    const entry = chatEntryFor(c.id);
    const available = contactMet(c) && !c.noChat && !!entry && !repliedThisChapter(c.id);
    if (!available) {
        return '<div class="ct-chat-block"><div class="ct-msg-disabled">' + esc(AT('noNewMessages')) + '</div>' +
        '<div class="ct-chat-hint">' + esc(AT('messageHint')) + '</div></div>';
    }
    return '<div class="ct-chat-block"><div class="ct-chat-hint">' + esc(AT('messageHint')) + '</div>' +
    '<button class="btn wide ct-msg-btn" onclick="openContactSync(\'' + esc(c.id) + '\')">' +
    esc(AT('message')) + ' · ' + esc(appL(c.name)) + '</button></div>';
}
function contactFactsHtml(c) {
    const nat = appL(c.nationality);
    const row = (label, value) => value == null || value === '' ? '' :
    '<div class="ct-fact"><span class="ct-fact-k">' + esc(label) + '</span>' +
    '<span class="ct-fact-v">' + esc(value) + '</span></div>';
    return '<div class="ct-facts">' +
    row(AT('gender'), appL(c.gender)) +
    row(AT('nat'), nat) +
    row(AT('email'), c.email && c.email !== '—' ? c.email : AT('noEmail')) +
    row(AT('occupation'), appL(contactRelation(c))) +
    '</div>';
}
function contactDossierHtml(c) {
    const status = contactStatusLine(c);
    return '<div class="ct-dossier">' +
    '<div class="ct-dossier-head">' +
    avatarHtml(c.name.en, 'ct-big-avatar') +
    '<div class="ct-dossier-id">' +
    '<h2>' + esc(appL(c.name)) + '</h2>' +
    '<div class="ct-dossier-role">' + esc(appL(c.role)) + '</div>' +
    '<div class="ct-dossier-meta"><span>' + esc(c.email || '') + '</span>' +
    '<span>' + esc(appNowLabel()) + '</span></div>' +
    '</div></div>' +
    contactFactsHtml(c) +
    '<div class="ct-section"><div class="ct-section-head">' + esc(AT('dossier')) + '</div>' +
    '<p class="ct-bio">' + fmt(appL(c.bio)) + '</p></div>' +
    (status ? '<div class="ct-section"><div class="ct-section-head">' + esc(AT('status')) + '</div>' +
        '<p class="ct-bio ct-status">' + fmt(appL(status)) + '</p></div>' : '') +
    contactMessageBlock(c) +
    (function () {
        const hist = mailHistoryHtml(c), syn = syncHistoryHtml(c), thr = threadHtml(c), jh = journalHistoryHtml();
        return (hist ? '<div class="ct-section"><div class="ct-section-head">' + esc(AT('history')) + '</div>' + hist + '</div>' : '') +
            (syn ? '<div class="ct-section"><div class="ct-section-head">' + esc(AT('chatHistory')) + '</div>' + syn + '</div>' : '') +
            (thr ? '<div class="ct-section"><div class="ct-section-head">' + esc(AT('threads')) + '</div>' + thr + '</div>' : '') +
            (jh ? '<div class="ct-section"><div class="ct-section-head">' + esc(AT('journal')) + '</div>' + jh + '</div>' : '');
    })() +
    '</div>';
}
function laplaceDossierHtml() {
    const c = contactById('laplace');
    const p = LAPLACE_PROFILE;
    const growth = p.growth[GS.ch] || p.growth[1];
    const tech = p.tech.map((row) =>
        '<div class="lp-tech-row"><span class="lp-tech-k">' + esc(appL(row.k)) + '</span>' +
        '<span class="lp-tech-v">' + esc(appL(row.v)) + '</span></div>').join('');
    const versions = p.versions.map((v) => {
            const reached = v.ch <= GS.ch;
            return '<div class="lp-ver' + (reached ? ' reached' : '') + '">' +
            '<span class="lp-dot"></span>' +
            '<div class="lp-ver-main"><div class="lp-ver-top"><span class="lp-ver-name">' + esc(v.v) + '</span>' +
            '<span class="lp-ver-date">' + esc(v.date) + '</span></div>' +
            '<div class="lp-ver-note">' + (reached ? esc(appL(v.note)) : esc(AT('locked'))) + '</div></div></div>';
        }).join('');
    const safety = p.safety.map((row) => '<li>' + esc(appL(row)) + '</li>').join('');
    return '<div class="ct-dossier lp-dossier">' +
    '<div class="ct-dossier-head">' +
    avatarHtml('Laplace', 'ct-big-avatar') +
    '<div class="ct-dossier-id"><h2>' + esc(appL(c.name)) + '</h2>' +
    '<div class="ct-dossier-role">' + esc(appL(c.role)) + '</div>' +
    '<div class="ct-dossier-meta"><span>' + esc(AT('modelPage')) + '</span><span>' + esc(AT('modelNoChat')) + '</span></div>' +
    '</div></div>' +
    '<div class="ct-section"><div class="ct-section-head">' + esc(AT('tech')) + '</div>' +
    '<p class="ct-bio">' + fmt(appL(p.intro)) + '</p>' +
    '<div class="lp-tech">' + tech + '</div></div>' +
    '<div class="ct-section"><div class="ct-section-head">' + esc(AT('versions')) + '</div>' +
    '<div class="lp-timeline">' + versions + '</div></div>' +
    '<div class="ct-section"><div class="ct-section-head">' + esc(AT('safety')) + '</div>' +
    '<ul class="lp-safety">' + safety + '</ul></div>' +
    '<div class="ct-section"><div class="ct-section-head">' + esc(AT('growth')) + '</div>' +
    '<p class="ct-bio lp-growth">' + fmt(appL(growth)) + '</p></div>' +
    '</div>';
}
function renderContacts() {
    const c = $('#c-contacts');
    if (!c) return;
    const prevListScroll = (($('.ct-list') || {}).scrollTop) || 0;
    ensureContactState();
    const met = metContactList();
    if (!met.length) { c.innerHTML = '<div class="apps-empty">' + esc(AT('notMet')) + '</div>'; return; }
    if (!GS.selContact || !contactById(GS.selContact) || !contactMet(contactById(GS.selContact))) {
        GS.selContact = met[0].id;
    }
    appsWithScroll('#c-contacts', () => {
            const models = met.filter((x) => x.type === 'ai');
            const main = met.filter((x) => x.type !== 'ai' && x.group !== 'support');
            const support = met.filter((x) => x.group === 'support');
            const listHtml =
            (models.length ? '<div class="ct-group-label">' + (GS.lang === 'zh' ? '模型' : 'Model') + '</div>' + groupRows(models) : '') +
            '<div class="ct-group-label">' + (GS.lang === 'zh' ? '人物' : 'People') + '</div>' + groupRows(main) +
            (support.length ? '<div class="ct-group-label">' + (GS.lang === 'zh' ? '其他' : 'Others') + '</div>' + groupRows(support) : '');
            const sel = contactById(GS.selContact) || met[0];
            const right = sel.type === 'ai' ? laplaceDossierHtml() : contactDossierHtml(sel);
            c.innerHTML =
            '<div class="contacts-layout">' +
            '<div class="ct-list">' +
            '<div class="ct-list-head">' + esc(AT('contactsSub')) + '</div>' + listHtml +
            '</div>' +
            '<div class="ct-detail">' + right + '</div>' +
            '</div>';
        });
    const ctList = $('.ct-list');
    if (ctList) ctList.scrollTop = prevListScroll;
    if (typeof updateDots === 'function') appSafe(() => updateDots(), null);
}

// ============================================================================
// WORKFLOW — timeline
// ============================================================================
function workflowStateOf(ev) {
    if (ev.ch > GS.ch) return 'locked';
    if (!ev.cond) return ev.ch === GS.ch ? 'current' : 'past';
    const ok = appSafe(() => !!ev.cond(), false);
    if (!ok) return 'skipped';
    return ev.ch === GS.ch ? 'current' : 'past';
}
function selectWorkflowEvent(id) {
    GS.workflowFocus = GS.workflowFocus === id ? null : id;
    renderWorkflow();
}
function workflowEventHtml(ev) {
    const state = workflowStateOf(ev);
    const open = GS.workflowFocus === ev.id;
    const tone = ev.tone || 'neutral';
    const date = appDate(ev.date);
    let body = '';
    if (state === 'locked') {
        body = '<div class="wf-desc muted">' + esc(AT('lockedNote')) + '</div>';
    } else if (state === 'skipped') {
        body = '<div class="wf-desc skipped-note">' + esc(AT('notOnPath')) + '</div>' +
        (open ? '<div class="wf-desc">' + fmt(appL(ev.desc)) + '</div>' : '');
    } else {
        body = (open ? '<div class="wf-desc">' + fmt(appL(ev.desc)) + '</div>' : '');
    }
    const stateLabel = state === 'current' ? AT('now') : (state === 'locked' ? AT('locked') : '');
    return '<div class="wf-event tone-' + tone + ' state-' + state + (open ? ' open' : '') + '"' +
    ' onclick="selectWorkflowEvent(\'' + esc(ev.id) + '\')">' +
    '<span class="wf-dot"></span>' +
    '<div class="wf-event-body">' +
    '<div class="wf-event-top"><span class="wf-title">' + esc(appL(ev.title)) + '</span>' +
    '<span class="wf-date">' + esc(date) + '</span>' +
    (stateLabel ? '<span class="wf-state">' + esc(stateLabel) + '</span>' : '') + '</div>' +
    body + '</div></div>';
}
function renderWorkflow() {
    const c = $('#c-workflow');
    if (!c) return;
    const summary = WORKFLOW_SUMMARY[GS.ch] || WORKFLOW_SUMMARY[1];
    const meta = appChapterMeta(GS.ch);
    const passed = WORKFLOW_EVENTS.filter((e) => {
            const st = workflowStateOf(e);
            return st !== 'locked' && st !== 'skipped';
        }).length;
    appsWithScroll('#c-workflow', () => {
            let html = '<div class="wf-wrap">' +
            '<div class="wf-summary"><div class="wf-summary-kicker">' + esc(AT('storySoFar')) + '</div>' +
            '<div class="wf-summary-title">' + esc(appChapterLabel(GS.ch) + ' · ' + appL(meta.title)) + '</div>' +
            '<div class="wf-summary-meta">' + esc(meta.date) + ' · ' + esc(appL(meta.loc)) + ' · ' + passed + ' ' + esc(AT('beats')) + '</div>' +
            '<p class="wf-summary-text">' + fmt(appL(summary)) + '</p></div>' +
            '<div class="wf-timeline">';
            for (let ch = 0; ch <= GS.ch; ch++) {
                const cm = appChapterMeta(ch);
                const current = ch === GS.ch;
                html += '<div class="wf-divider' + (current ? ' current' : '') + '">' +
                '<span class="wf-divider-dot"></span>' +
                '<span class="wf-ch">' + esc(appChapterLabel(ch)) + '</span>' +
                '<span class="wf-ch-title">' + esc(appL(cm.title)) + '</span>' +
                '<span class="wf-ch-date">' + esc(cm.date) + '</span>' +
                '</div>';
                const events = WORKFLOW_EVENTS.filter((e) => e.ch === ch);
                html += events.map(workflowEventHtml).join('');
                if (!events.length) html += '<div class="wf-empty">—</div>';
            }
            if (GS.ch < 7) {
                html += '<div class="wf-divider locked wf-locked-placeholder">' +
                '<span class="wf-divider-dot"></span>' +
                '<span class="wf-ch">' + esc(appChapterLabel(GS.ch + 1)) + '</span>' +
                '<span class="wf-ch-title">·· ' + esc(AT('locked')) + ' ··</span>' +
                '</div>' +
                '<div class="wf-locked-note">' + esc(AT('lockedNote')) + '</div>';
            }
            html += '</div></div>';
            c.innerHTML = html;
        });
}

// ============================================================================
// FILES — app, attachments, viewer
// ============================================================================
function appsEnsureState() {
    if (!(GS.files instanceof Set)) GS.files = new Set(GS.files || []);
    if (!GS.affinity || typeof GS.affinity !== 'object') GS.affinity = {};
    if (!GS.contactThreads || typeof GS.contactThreads !== 'object') GS.contactThreads = {};
    if (!GS.contactDone || typeof GS.contactDone !== 'object') GS.contactDone = {};
    if (!GS.fileCat) GS.fileCat = 'all';
    if (GS.selContact === undefined) GS.selContact = null;
    if (GS.selFile === undefined) GS.selFile = null;
    if (GS.workflowFocus === undefined) GS.workflowFocus = null;
}
function downloadedFiles() {
    appsEnsureState();
    return FILES_DATA.filter((f) => GS.files.has(f.id));
}
function fileViewIcon(view) {
    if (view === 'map') return '🗺️';
    if (view === 'image') return '🖼️';
    if (view === 'postcard') return '🏞️';
    if (view === 'businesscard') return '💼';
    if (view === 'formula') return '∑';
    if (view === 'record') return '🪪';
    return '📄';
}
function fileCatCount(cat) {
    const files = downloadedFiles();
    if (cat === 'all') return files.length;
    return files.filter((f) => f.cat === cat).length;
}
function selectFileCategory(cat) {
    appsEnsureState();
    GS.fileCat = cat;
    renderFiles();
}
function fileCardHtml(f) {
    const icon = f.src
        ? '<div class="fl-card-icon"><img src="' + esc(f.src) + '" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:3px;display:block;"></div>'
        : '<div class="fl-card-icon">' + fileViewIcon(f.view) + '</div>';
    return '<div class="fl-card" onclick="openFileViewer(\'' + esc(f.id) + '\')">' +
    icon +
    '<div class="fl-card-main"><div class="fl-card-name">' + esc(appL(f.name)) + '</div>' +
    '<div class="fl-card-meta">' + esc(appL(f.kind)) + '</div>' +
    '<div class="fl-card-date">' + esc(appDate(f.date)) + ' · ' + esc(appL(f.source)) + '</div></div>' +
    '<div class="fl-card-open">' + esc(AT('open')) + '</div></div>';
}
function renderFiles() {
    const c = $('#c-files');
    if (!c) return;
    appsEnsureState();
    const cats = ['all', 'work', 'legal', 'personal', 'evidence', 'map', 'photo', 'medical'];
    const files = downloadedFiles();
    const sel = cats.indexOf(GS.fileCat) >= 0 ? GS.fileCat : 'all';
    const list = sel === 'all' ? files.slice() : files.filter((f) => f.cat === sel);
    list.sort((a, b) => (String(b.date || '') + (b.id || '')).localeCompare(String(a.date || '') + (a.id || '')));
    const side = cats.map((cat) => {
            const n = fileCatCount(cat);
            const label = cat === 'all' ? AT('catAll') : fileCatLabel(cat);
            return '<div class="fl-cat' + (sel === cat ? ' active' : '') + (n === 0 ? ' empty' : '') +
            '" onclick="selectFileCategory(\'' + cat + '\')"><span class="fl-cat-name">' + esc(label) + '</span>' +
            '<span class="fl-cat-n">' + n + '</span></div>';
        }).join('');
    const grid = list.length
    ? '<div class="fl-grid">' + list.map(fileCardHtml).join('') + '</div>'
    : '<div class="fl-empty">' + esc(sel === 'all' ? AT('filesEmpty') : AT('filesEmptyCat')) + '</div>';
    appsWithScroll('#c-files', () => {
            c.innerHTML =
            '<div class="files-layout">' +
            '<div class="fl-side"><div class="fl-side-head">' + esc(AT('filesSub')) + '</div>' + side +
            '<div class="fl-side-note">' + esc(AT('downloadHint')) + '</div></div>' +
            '<div class="fl-main"><div class="fl-main-head"><span>' + esc(AT('filesSub')) + '</span>' +
            '<span class="fl-count">' + files.length + ' / ' + FILES_DATA.length + '</span></div>' +
            (files.length ? grid : '<div class="fl-empty">' + esc(AT('filesEmpty')) + '</div>') +
            '</div></div>';
        });
}

// ---------------------------------------------------------------- mail attachment chips
function mailAttachmentsHtml(m) {
    if (!m || !m.attachments || !m.attachments.length) return '';
    appsEnsureState();
    const chips = m.attachments.map((id) => {
            const f = fileById(id);
            if (!f) return '';
            const done = GS.files.has(id);
            return '<button class="attach-chip' + (done ? ' done' : '') + '" ' +
            'onclick="' + (done ? 'openFileViewer' : 'downloadAttachment') + '(\'' + esc(id) + '\')" ' +
            'title="' + esc(appL(f.name)) + '">' +
            '<span class="ac-icon">' + fileViewIcon(f.view) + '</span>' +
            '<span class="ac-main"><span class="ac-name">' + esc(appL(f.name)) + '</span>' +
            '<span class="ac-meta">' + esc(appL(f.kind)) + ' · ' + (done ? esc(AT('downloaded')) : esc(AT('download'))) + '</span></span>' +
            '<span class="ac-state">' + (done ? '✓' : '⬇') + '</span></button>';
        }).join('');
    if (!chips) return '';
    return '<div class="mail-attachments"><div class="ma-label">' + esc(AT('attachments')) +
    ' <span class="ma-count">' + m.attachments.length + '</span></div>' +
    '<div class="ma-chips">' + chips + '</div></div>';
}
function downloadAttachment(id) {
    appsEnsureState();
    const f = fileById(id);
    if (!f) { appToast(AT('unknownFile'), 'warn'); return; }
    if (GS.files.has(id)) { openFileViewer(id); return; }
    GS.files.add(id);
    appPlay('success');
    appToast(AT('downloadedToast') + ' · ' + appL(f.name), 'ok');
    const mailWin = document.querySelector('.window[data-app="mail"]');
    if (mailWin && typeof renderMail === 'function') appSafe(() => renderMail(), null);
    const filesWin = document.querySelector('.window[data-app="files"]');
    if (filesWin) appSafe(() => renderFiles(), null);
    if (typeof updateUI === 'function') appSafe(() => updateUI(), null);
}
function openAttachmentFile(id) { openFileViewer(id); }

// ---------------------------------------------------------------- viewer shell
function clearFileTypewriter() {
    if (GS.fileTwTimer) { clearInterval(GS.fileTwTimer); GS.fileTwTimer = null; }
}
function fileViewerMeta(f) {
    return '<div class="fv-meta">' +
    '<span class="fv-kind">' + fileViewIcon(f.view) + ' ' + esc(appL(f.kind)) + '</span>' +
    '<span>' + esc(AT('source')) + ': ' + esc(appL(f.source)) + '</span>' +
    '<span>' + esc(appDate(f.date)) + '</span>' +
    '</div>';
}
function openFileViewer(id) {
    appsEnsureState();
    const f = fileById(id);
    if (!f) { appToast(AT('unknownFile'), 'warn'); return; }
    if (!GS.files.has(id)) { downloadAttachment(id); return; }
    clearFileTypewriter();
    GS.selFile = id;
    let content = '';
    if (f.src) {
        content = '<div class="fv-canvas-wrap" style="display:flex;align-items:center;justify-content:center;padding:0;background:#0d0f14;">' +
            '<img class="fv-image" src="' + esc(f.src) + '" alt="' + esc(appL(f.name)) + '" ' +
            'style="display:block;max-width:100%;max-height:62vh;object-fit:contain;">' +
            '</div>' +
            (f.body ? '<div class="fv-hint" style="text-align:left;line-height:1.55;">' + fmt(appL(f.body)) + '</div>' : '');
    } else if (f.view === 'text') {
        content = '<div class="fv-pdf" style="background:#fbfaf6;color:#1f2024;padding:26px 30px;border-radius:10px;' +
            'line-height:1.75;font-size:12.5px;white-space:pre-wrap;word-break:break-word;text-align:left;' +
            'max-height:62vh;overflow-y:auto;box-shadow:0 6px 20px rgba(0,0,0,.25);">' +
            fmt(appL(f.body)) + '</div>';
    } else {
        content = '<div class="fv-canvas-wrap"><canvas id="fv-canvas" width="680" height="440"></canvas></div>';
    }
    const box = openModal(
        '<div class="fv-head"><div class="fv-title">' + esc(appL(f.name)) + '</div>' +
        '<button class="fv-close" onclick="closeFileViewer()">×</button></div>' +
        fileViewerMeta(f) + content,
        { boxClass: 'file-viewer-modal' }
    );
    if (!box) return;
    if (f.src) { /* image rendered directly */ }
    else if (f.view === 'text') { /* static page, no typewriter */ }
    else {
        const cv = document.getElementById('fv-canvas');
        if (cv) drawFileCanvas(cv, f);
    }
    appPlay('click');
}
function startFileTypewriter(f) {
    const el = document.getElementById('fv-text');
    if (!el) return;
    const text = appL(f.body);
    el.textContent = '';
    el.onclick = () => { finishFileTypewriter(text, el); };
    let i = 0;
    GS.fileTwTimer = setInterval(() => {
            if (!document.body.contains(el)) { clearFileTypewriter(); return; }
            el.textContent = text.slice(0, i);
            i += Math.max(1, Math.round(text.length / 260));
            if (i >= text.length) finishFileTypewriter(text, el);
        }, 16);
}
function finishFileTypewriter(text, el) {
    clearFileTypewriter();
    if (el && document.body.contains(el)) el.textContent = text;
}
function closeFileViewer() {
    clearFileTypewriter();
    GS.selFile = null;
    closeModal();
}
function resetAppsState() {
    clearFileTypewriter();
    GS.files = new Set();
    GS.affinity = {};
    GS.contactThreads = {};
    GS.contactDone = {};
    GS.contactSeen = new Set();
    GS._csLastCh = null;
    GS.selContact = null;
    GS.selFile = null;
    GS.workflowFocus = null;
    GS.fileCat = 'all';
}

// ---------------------------------------------------------------- canvas helpers
function TXT(en, zh) { return GS.lang === 'zh' ? zh : en; }
function cvPaper(ctx, w, h, tint) {
    ctx.fillStyle = tint || '#f5f1e4';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(0,0,0,.10)';
    ctx.lineWidth = 2;
    ctx.strokeRect(10, 10, w - 20, h - 20);
    ctx.fillStyle = 'rgba(0,0,0,.035)';
    for (let y = 24; y < h - 14; y += 26) ctx.fillRect(18, y, w - 36, 1);
}
function cvText(ctx, text, x, y, size, color, weight, align) {
    ctx.fillStyle = color || '#2b2a26';
    ctx.font = (weight || '400') + ' ' + (size || 14) + 'px "Helvetica Neue", "PingFang SC", "Microsoft YaHei", sans-serif';
    ctx.textAlign = align || 'left';
    ctx.fillText(text, x, y);
    ctx.textAlign = 'left';
}
function cvWrap(ctx, text, x, y, maxW, lh, size, color) {
    ctx.fillStyle = color || '#2b2a26';
    ctx.font = (size || 14) + 'px "Helvetica Neue", "PingFang SC", sans-serif';
    const words = String(text).split(' ');
    let line = '';
    let yy = y;
    for (let i = 0; i < words.length; i++) {
        const test = line ? line + ' ' + words[i] : words[i];
        if (ctx.measureText(test).width > maxW && line) {
            ctx.fillText(line, x, yy);
            line = words[i];
            yy += lh;
        } else line = test;
    }
    if (line) ctx.fillText(line, x, yy);
    return yy;
}
function drawFileCanvas(cv, f) {
    const ctx = cv.getContext('2d');
    const w = cv.width, h = cv.height;
    if (!ctx) return;
    if (f.view === 'map') {
        if (f.id === 'f_reindeer_map') drawReindeerMap(ctx, w, h);
        else if (f.id === 'f_zurich_map2') drawAuditFloor(ctx, w, h);
        else drawZurichMap(ctx, w, h);
    } else if (f.view === 'postcard') drawPostcardPlaceholder(ctx, w, h);
    else if (f.view === 'businesscard') drawBusinessCard(ctx, w, h);
    else if (f.view === 'formula') drawFormulaSheet(ctx, w, h);
    else drawRecord(ctx, w, h, f);
}
