function drawReindeerMap(ctx, w, h) {
    cvPaper(ctx, w, h, '#f7f5ee');
    // contours
    ctx.strokeStyle = 'rgba(90,110,120,.28)'; ctx.lineWidth = 1;
    for (let i = 0; i < 9; i++) {
        ctx.beginPath();
        ctx.moveTo(40, 80 + i * 34);
        ctx.bezierCurveTo(200, 40 + i * 34, 420, 120 + i * 30, w - 40, 80 + i * 34);
        ctx.stroke();
    }
    // site polygon
    ctx.fillStyle = 'rgba(40,90,160,.14)';
    ctx.strokeStyle = '#2a5aa0'; ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(430, 150); ctx.lineTo(600, 130); ctx.lineTo(620, 300); ctx.lineTo(470, 330); ctx.closePath();
    ctx.fill(); ctx.stroke();
    cvText(ctx, TXT('proposed site', '拟建场址'), 470, 260, 14, '#2a5aa0', '700');
    // migration routes
    ctx.strokeStyle = '#c23a2e'; ctx.lineWidth = 3;
    [[40, 330, 240, 250, 470, 220], [60, 200, 260, 190, 420, 230], [40, 380, 300, 390, 460, 330]].forEach((p) => {
            ctx.beginPath();
            ctx.moveTo(p[0], p[1]);
            ctx.quadraticCurveTo(p[2], p[3], p[4], p[5]);
            ctx.stroke();
        });
    // calving ground
    ctx.strokeStyle = '#8a4a1d'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(180, 250, 26, 0, Math.PI * 2); ctx.stroke();
    cvText(ctx, 'April', 156, 292, 13, '#8a4a1d', '700');
    // NO
    ctx.fillStyle = '#c23a2e';
    ctx.font = '800 34px "Helvetica Neue", sans-serif';
    ctx.fillText('NO', 500, 210);
    cvText(ctx, TXT('reindeer migration · seasonal routes', '驯鹿迁徙 · 季节路线'), 40, h - 34, 13, '#4b4a44', '500');
    cvText(ctx, TXT('Kiruna herding district · field copy', 'Kiruna 放牧区 · 野外用图'), 40, h - 58, 13, '#4b4a44', '500');
}
