function drawFormulaSheet(ctx, w, h) {
    cvPaper(ctx, w, h, '#fbfaf4');
    const ox = 70, oy = 250, axisW = 300, axisH = 160;
    ctx.strokeStyle = '#3c3a34'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy - axisH); ctx.lineTo(ox, oy); ctx.lineTo(ox + axisW, oy); ctx.stroke();
    // curves
    function curve(fn, color, label) {
        ctx.strokeStyle = color; ctx.lineWidth = 2.5; ctx.beginPath();
        for (let i = 0; i <= 120; i++) {
            const t = i / 120;
            const x = ox + t * axisW;
            const y = oy - fn(t) * axisH;
            if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.stroke();
        cvText(ctx, label, ox + axisW - 4, oy - axisH - 6, 12, color, '600', 'right');
    }
    const gauss = (t) => Math.exp(-Math.pow((t - 0.5) * 6, 2));
    const laplaceCurve = (t) => Math.exp(-Math.abs((t - 0.5) * 12)) * 0.9;
    const poisson = (t) => Math.exp(-Math.pow((t - 0.62) * 9, 2)) * 0.78;
    curve(gauss, '#1d4d8f', 'Normal');
    curve(laplaceCurve, '#c23a2e', 'Laplace');
    curve(poisson, '#2f7d4f', 'Poisson');
    cvText(ctx, TXT('0', '0'), ox - 4, oy + 20, 11, '#6a685e', '400');
    cvText(ctx, TXT('x', 'x'), ox + axisW - 4, oy + 20, 12, '#3c3a34', '600');
    // formulas panel
    ctx.fillStyle = 'rgba(0,0,0,.04)';
    ctx.fillRect(410, 70, w - 470, h - 150);
    cvText(ctx, 'Normal(μ, σ²)', 430, 108, 18, '#1d4d8f', '700');
    cvText(ctx, 'μ = mean σ² = variance', 430, 132, 13, '#3c3a34', '400');
    cvText(ctx, 'symmetric · light tails', 430, 152, 12, '#6a685e', '400');
    cvText(ctx, 'Laplace(μ, b)', 430, 194, 18, '#c23a2e', '700');
    cvText(ctx, 'μ = mean variance = 2b²', 430, 218, 13, '#3c3a34', '400');
    cvText(ctx, 'sharp peak · heavy tails', 430, 238, 12, '#6a685e', '400');
    cvText(ctx, 'Poisson(λ)', 430, 280, 18, '#2f7d4f', '700');
    cvText(ctx, 'mean = variance = λ', 430, 304, 13, '#3c3a34', '400');
    cvText(ctx, TXT('counts of rare events', '稀有事件计数'), 430, 324, 12, '#6a685e', '400');
    cvText(ctx, TXT('If the outlier is the story, do not average it away.', '如果离群值就是故事本身，不要把它平均掉。'), 70, h - 34, 13, '#4b4a44', '500');
}
