    c5_zoe_stockholm: 'stockholm', c5_claire_sync: 'synctest', c5_travel_ticket: 'booking', c5_claire_retro: 'sync',
    c6_zoe_incident: 'zoe', c6_senja_request: 'senja', c6_nadine_legal: 'legal', c6_zoe_audit_return: 'auditReturn',
    c6_zoe_logged: 'refuse', c6_alan_angry: 'refuseAlan', c6_senja_regret: 'refuseSenja', c6_iran_thanks: 'refuseIran',
    c6_zoe_forwarded: 'forward', c6_iran_explanation: 'recipes', c6_senja_thanks: 'thanks',
