// ---------------------------------------------------------------- text helpers
function syncL(v) {
    if (v == null) return '';
    if (typeof v === 'string') return v;
    if (typeof appL === 'function') { try { return appL(v); } catch (e) { } }
    return v.en || v.zh || '';
}
function syncIsObj(v) { return v && typeof v === 'object'; }
function syncNorm(v) { return String(v == null ? '' : v).toLowerCase().replace(/\s+/g, ' ').trim(); }
function syncPad2(n) { n = Number(n) || 0; return (n < 10 ? '0' : '') + n; }
function syncClockFromOrd(ord) {
    const base = 8 * 60 + 40 + (Number(ord) || 0) * 2;
    return syncPad2(Math.floor((base / 60) % 24)) + ':' + syncPad2(base % 60);
}
function syncMessageStamp(ord, m) {
    if (m && m.time) return String(m.time);
    return syncClockFromOrd(ord);
}
function syncBubbleText(text) {
    const raw = (typeof text === 'string') ? text : syncL(text);
    let s = String(raw == null ? '' : raw).replace(/\r\n?/g, '\n');
    s = s.replace(/[ \t]+$/gm, '').replace(/\n{3,}/g, '\n\n').trim();
    return esc(s);
}

// Removed-storyline guard. Names are assembled so this module stays clean.
const SYNC_REMOVED_RE = new RegExp(
    ['wan' + 'g', 'wei' + 'wu', 'math' + 'ieu', 'lav' + 'oie',
     'hang' + 'zhou', '\\u4f1f\\u6b66', '\\u9a6c\\u4fee', '\\u676d\\u5dde'].join('|'), 'i');
function syncTextContainsRemoved(v) {
    if (v == null) return false;
    const s = (typeof v === 'string') ? v : (syncL(v) + ' ' + (syncIsObj(v) ? (v.zh || '') : ''));
    return SYNC_REMOVED_RE.test(String(s || ''));
}

