// ---------------------------------------------------------------- contact entries
function syncReplyForEntry(entry, choice, idx) {
    if (!entry || !choice) return null;
    const candidates = [
        choice.reply, choice.r, choice.response, choice.followup, choice.followUp,
        (entry.replies && entry.replies[idx]),
        (entry.reply && entry.reply[idx]),
        (entry.answers && entry.answers[idx])
    ];
    for (let i = 0; i < candidates.length; i++) {
        const c = candidates[i];
        if (c == null) continue;
        if (typeof c === 'string' && c) return { en: c, zh: c };
        if (syncIsObj(c) && (c.en || c.zh)) return c;
    }
    return null;
}
function syncEntryChoices(entry) {
    if (!entry || !Array.isArray(entry.choices)) return [];
    return entry.choices.filter(function (ch) { return ch && ch.t != null; });
}
function syncEntryValid(entry) {
    if (!entry || entry.prompt == null) return false;
    const choices = syncEntryChoices(entry);
    if (choices.length < 2 || choices.length > 3) return false;
    for (let i = 0; i < choices.length; i++) {
        if (!syncReplyForEntry(entry, choices[i], i)) return false;
        if (syncTextContainsRemoved(choices[i].t) || syncTextContainsRemoved(syncReplyForEntry(entry, choices[i], i))) return false;
    }
    return !syncTextContainsRemoved(entry.prompt);
}
function syncAllAuthoredSyncs() {
    const data = (typeof CH_DATA !== 'undefined' && CH_DATA[GS.ch]) ? CH_DATA[GS.ch] : null;
    return (data && data.syncs) ? data.syncs : [];
}
function syncDmChannels() {
    const out = [];
    const all = syncAllAuthoredSyncs();
    for (let i = 0; i < all.length; i++) {
        const ch = all[i] && all[i].ch;
        if (!ch || typeof ch !== 'string' || ch.charAt(0) === '#') continue;
        if (out.indexOf(ch) < 0) out.push(ch);
    }
    return out;
}
function syncNameCore(v) {
    return syncNorm(v)
        .replace(/^(dr\.?|mr\.?|ms\.?|mrs\.?|mme\.?)\s+/, '')
        .replace(/[^\p{L}\p{N} ]+/gu, '')
        .replace(/\s+/g, ' ')
        .trim();
}
function syncContactMatchesChannel(c, ch) {
    if (!c || !ch) return false;
    const low = syncNameCore(ch);
    if (!low) return false;
    const nm = syncNameCore(c.name && c.name.en);
    if (nm && (low.indexOf(nm) >= 0 || nm.indexOf(low) >= 0)) return true;
    const aliases = c.aliases || [];
    for (let i = 0; i < aliases.length; i++) {
        const a = syncNameCore(aliases[i]);
        if (a && low.indexOf(a) >= 0) return true;
    }
    if (typeof contactMatchesMail === 'function') {
        try { if (contactMatchesMail(c, { from: ch, email: '' })) return true; } catch (e) { }
    }
    return false;
}
function syncMainlineContactIds() {
    const set = new Set();
    const dms = syncDmChannels();
    if (!dms.length) return set;
    const contacts = (typeof CONTACTS !== 'undefined') ? CONTACTS : [];
    for (let i = 0; i < contacts.length; i++) {
        const c = contacts[i];
        for (let j = 0; j < dms.length; j++) {
            if (syncContactMatchesChannel(c, dms[j])) { set.add(c.id); break; }
        }
    }
    return set;
}
function syncRawChatEntries(ch) {
    let out = [];
    if (typeof CONTACT_CHATS !== 'undefined' && CONTACT_CHATS && CONTACT_CHATS[ch]) {
        out = out.concat(CONTACT_CHATS[ch]);
    }
    if (SYNC_CHAT_POOL[ch]) out = out.concat(SYNC_CHAT_POOL[ch]);
    return out;
}
function syncEntryCid(e) {
    if (!e) return null;
    return e.cid || e.contact || e.contactId || e.id || null;
}
function syncOptionalChats() {
    if (typeof CONTACTS === 'undefined' || typeof contactById !== 'function') return [];
    const ch = GS.ch;
    const mainline = syncMainlineContactIds();
    const raw = syncRawChatEntries(ch);
    const order = [];
    const byCid = {};
    for (let i = 0; i < raw.length; i++) {
        const e = raw[i];
        const cid = syncEntryCid(e);
        if (!cid) continue;
        if (!byCid[cid]) { byCid[cid] = e; order.push(cid); }
        else if (!syncEntryValid(byCid[cid]) && syncEntryValid(e)) byCid[cid] = e;
    }
    const out = [];
    for (let i = 0; i < order.length; i++) {
        const cid = order[i];
        const c = contactById(cid);
        if (!c || !contactMet(c)) continue;
        if (c.noChat || c.type === 'ai') continue;
        if (mainline.has(cid)) continue;
        const e = byCid[cid];
        if (!syncEntryValid(e)) continue;
        out.push({ id: cid, contact: c, entry: e, key: 'contact:' + cid });
        if (out.length >= 3) break;
    }
    return out;
}
function syncOptionalEntryFor(cid) {
    if (!cid) return null;
    const list = syncOptionalChats();
    for (let i = 0; i < list.length; i++) if (list[i].id === cid) return list[i].entry;
    return null;
}
function syncOptionalItemFor(cid) {
    if (!cid) return null;
    const list = syncOptionalChats();
    for (let i = 0; i < list.length; i++) if (list[i].id === cid) return list[i];
    return null;
}

// ---------------------------------------------------------------- thread state
function syncEnsureState() {
    if (GS._syncChapter !== GS.ch) {
        GS._syncChapter = GS.ch;
        GS.contactSyncTyping = null;
        if (GS.typing) GS.typing = {};
        GS.selfTyping = null;
        GS.syncMsgScroll = {};
        GS.syncRenderCount = {};
        GS.syncListScroll = 0;
        GS._syncJumpTo = null;
        GS._syncSkipCapture = false;
    }
    if (!(GS.contactThreads instanceof Object)) GS.contactThreads = {};
    if (GS._syncThreadsRef !== GS.contactThreads) {
        // new game / reset: the thread store was replaced
        GS._syncThreadsRef = GS.contactThreads;
        GS.syncGlobalSeq = 0;
        GS.syncOrderMap = {};
        GS.syncPromptGord = {};
        GS.syncMsgScroll = {};
        GS.syncRenderCount = {};
    }
    if (!(GS.contactDone instanceof Object)) GS.contactDone = {};
    if (!(GS.syncMsgScroll instanceof Object)) GS.syncMsgScroll = {};
    if (!(GS.syncOrderMap instanceof Object)) GS.syncOrderMap = {};
    if (!(GS.syncPromptGord instanceof Object)) GS.syncPromptGord = {};
    if (!(Number(GS.syncGlobalSeq) >= 0)) GS.syncGlobalSeq = 0;
    if (!(GS.syncRenderCount instanceof Object)) GS.syncRenderCount = {};
    if (!(GS.syncTimers instanceof Array)) GS.syncTimers = [];
    if (!(GS.seenChs instanceof Set)) GS.seenChs = new Set();
}
function syncThreadOf(id) {
    syncEnsureState();
    if (!Array.isArray(GS.contactThreads[id])) GS.contactThreads[id] = [];
    return GS.contactThreads[id];
}
// Every rendered Sync message gets one persistent display ordinal. Base
// messages are numbered in authored/reveal order when first seen; contact
// thread entries are numbered when created. The counter survives chapter
// reloads, so a newer message can never be sorted before an older one.
function syncNextGlobal() {
    GS.syncGlobalSeq = (Number(GS.syncGlobalSeq) || 0) + 1;
    return GS.syncGlobalSeq;
}
function syncBaseKey(m) {
    const data = (typeof CH_DATA !== 'undefined' && CH_DATA[GS.ch]) ? CH_DATA[GS.ch] : null;
    const idx = (data && data.syncs) ? data.syncs.indexOf(m) : -1;
    return GS.ch + '|b|' + idx;
}
function syncEnsureBaseOrders(revealed) {
    syncEnsureState();
    const list = revealed.slice().sort(function (a, b) {
        const d = syncBaseOrdinal(a) - syncBaseOrdinal(b);
        if (d) return d;
        const ka = syncBaseKey(a), kb = syncBaseKey(b);
        return ka < kb ? -1 : (ka > kb ? 1 : 0);
    });
    for (let i = 0; i < list.length; i++) {
        const m = list[i];
        const key = syncBaseKey(m);
        if (!GS.syncOrderMap[key]) GS.syncOrderMap[key] = syncNextGlobal();
    }
}
function syncBaseGord(m) {
    const key = syncBaseKey(m);
    return GS.syncOrderMap[key] || 0;
}
function syncPromptGord(id) {
    syncEnsureState();
    const key = GS.ch + ':' + id;
    if (!GS.syncPromptGord[key]) GS.syncPromptGord[key] = syncNextGlobal();
    return GS.syncPromptGord[key];
}
function syncNormalizeThread(id) {
    syncEnsureState();
    const th = syncThreadOf(id);
    const maxByCh = {};
    for (let i = 0; i < th.length; i++) {
        const e = th[i];
        if (e == null || typeof e !== 'object') continue;
        if (e.ch == null) e.ch = 0;
        if (typeof e.ord === 'number' && e.ord > (maxByCh[e.ch] || 0)) maxByCh[e.ch] = e.ord;
    }
    for (let i = 0; i < th.length; i++) {
        const e = th[i];
        if (e == null || typeof e !== 'object') continue;
        if (typeof e.ord !== 'number') {
            maxByCh[e.ch] = (maxByCh[e.ch] || 0) + 1;
            e.ord = maxByCh[e.ch];
        }
        if (!e.stamp) e.stamp = syncClockFromOrd(e.ord);
    }
    const ordered = th.slice().sort(function (a, b) {
        if (a.ch !== b.ch) return a.ch - b.ch;
        return (a.ord || 0) - (b.ord || 0);
    });
    for (let i = 0; i < ordered.length; i++) {
        if (typeof ordered[i].gord !== 'number') ordered[i].gord = syncNextGlobal();
    }
    return th;
}
function syncPushThread(id, item) {
    const th = syncThreadOf(id);
    th.push(item);
    return item;
}
function syncBaseOrdinal(m) {
    const n = Number(m && m._chatOrder);
    if (n > 0) return n;
    const data = (typeof CH_DATA !== 'undefined' && CH_DATA[GS.ch]) ? CH_DATA[GS.ch] : null;
    const idx = data && data.syncs ? data.syncs.indexOf(m) : -1;
    return idx >= 0 ? idx + 1 : 0;
}
function syncKindRank(k) {
    return k === 'base' ? 0 : (k === 'thread' ? 1 : 2);
}

// ---------------------------------------------------------------- channel model
function syncBaseChannels() {
    const all = (typeof visibleSyncs === 'function') ? visibleSyncs() : [];
    const out = [];
    for (let i = 0; i < all.length; i++) {
        const ch = all[i] && all[i].ch;
        if (!ch) continue;
        if (out.indexOf(ch) < 0) out.push(ch);
    }
    return out;
}
function syncChannelPreview(ch, revealed) {
    const list = revealed.filter(function (m) { return m.ch === ch; });
    const last = list.length ? list[list.length - 1] : null;
    if (GS.typing && GS.typing[ch]) return CT('typing');
    if (GS.selfTyping === ch) return CT('typing');
    return last ? syncL(last.t) : '';
}
function syncContactPreview(item) {
    const th = (GS.contactThreads && GS.contactThreads[item.id]) || [];
    let last = null;
    for (let i = th.length - 1; i >= 0; i--) if (th[i] && th[i].text) { last = th[i]; break; }
    if (last) return syncL(last.text);
    if (!repliedThisChapterSafe(item.id)) return syncL(item.entry.prompt);
    return CT('noMsg');
}
function repliedThisChapterSafe(id) {
    if (typeof repliedThisChapter === 'function') { try { return !!repliedThisChapter(id); } catch (e) { } }
    const th = (GS.contactThreads && GS.contactThreads[id]) || [];
    for (let i = 0; i < th.length; i++) if (th[i] && th[i].ch === GS.ch && th[i].from === 'you') return true;
    return false;
}
function syncSeenRevealed() {
    const all = (typeof visibleSyncs === 'function') ? visibleSyncs() : [];
    if (typeof isSyncRevealed !== 'function') return all;
    return all.filter(function (m) { try { return isSyncRevealed(m); } catch (e) { return true; } });
}

// ---------------------------------------------------------------- message rows
function syncRowHtml(opts) {
    const self = !!opts.self;
    const sender = self ? (GS.playerName || 'You') : opts.sender;
    const showAvatar = !!opts.showAvatar;
    return '<div class="msg-row ' + (self ? 'self' : 'other') + '">' +
    (self ? '' : (showAvatar ? avatarHtml(sender, 'avatar-sm') : '<span class="avatar-spacer"></span>')) +
    '<div class="msg-stack">' +
    (showAvatar ? '<div class="msg-sender">' + esc(sender) + '</div>' : '') +
    '<div class="msg ' + (self ? 'self' : 'other') + '"><div class="msg-text">' + syncBubbleText(opts.text) + '</div></div>' +
    '</div></div>';
}
function syncTypingRow(sender, self) {
    return '<div class="msg-row ' + (self ? 'self' : 'other') + '"><div class="msg-stack">' +
    (self ? '' : '<div class="msg-sender">' + esc(sender) + '</div>') +
    '<div class="msg ' + (self ? 'self' : 'other') + ' typing-bubble"><span></span><span></span><span></span></div>' +
    '</div></div>';
}

// Build the unified, ordered event list for a contact conversation.
// Ordering key: chapter, then ordinal. Message bodies are never spliced into
// earlier rows: the whole list is sorted once, then rendered.
function syncContactEvents(item) {
    const c = item.contact;
    const id = item.id;
    syncEnsureBaseOrders(syncSeenRevealed());
    const th = syncNormalizeThread(id);
    const events = [];
    for (let i = 0; i < th.length; i++) {
        const e = th[i];
        if (!e || (!e.text && !e.prompt)) continue;
        if (e.ch < GS.ch) events.push({ kind: 'thread', ord: e.gord || 0, e: e });
    }
    const baseCh = (typeof csBaseChannelForContact === 'function') ? csBaseChannelForContact(c) : null;
    if (baseCh) {
        const revealed = syncSeenRevealed().filter(function (m) { return m.ch === baseCh; });
        revealed.sort(function (a, b) { return syncBaseOrdinal(a) - syncBaseOrdinal(b); });
        for (let i = 0; i < revealed.length; i++) {
            events.push({ kind: 'base', ord: syncBaseGord(revealed[i]), m: revealed[i] });
        }
    }
    for (let i = 0; i < th.length; i++) {
        const e = th[i];
        if (!e || e.ch !== GS.ch) continue;
        if (!e.text && !e.prompt) continue;
        events.push({ kind: 'thread', ord: e.gord || 0, e: e });
    }
    const pending = !repliedThisChapterSafe(id);
    if (pending) {
        events.push({ kind: 'prompt', ord: syncPromptGord(id) });
    }
    events.sort(function (x, y) {
        if (x.ord !== y.ord) return x.ord - y.ord;
        return syncKindRank(x.kind) - syncKindRank(y.kind);
    });
    return { events: events, pending: pending };
}

function syncContactThreadHtml(item) {
    const c = item.contact;
    const built = syncContactEvents(item);
    const events = built.events;
    let out = '';
    let prevSender = null;
    const contactName = syncL(c.name);
    for (let i = 0; i < events.length; i++) {
        const ev = events[i];
        if (ev.kind === 'base') {
            const m = ev.m;
            const self = !!m.self;
            const sender = self ? (GS.playerName || 'You') : (m.s || contactName);
            const show = !self && sender !== prevSender;
            prevSender = self ? null : sender;
            out += syncRowHtml({ self: self, sender: sender, showAvatar: show, text: m.t, stamp: syncMessageStamp(ev.ord, m) });
        } else if (ev.kind === 'thread') {
            const e = ev.e;
            const self = e.from === 'you';
            const sender = self ? (GS.playerName || 'You') : contactName;
            const show = !self && sender !== prevSender;
            prevSender = self ? null : sender;
            out += syncRowHtml({ self: self, sender: sender, showAvatar: show, text: e.text, stamp: e.stamp || syncClockFromOrd(ev.ord) });
        } else if (ev.kind === 'prompt') {
            const show = contactName !== prevSender;
            prevSender = contactName;
            out += syncRowHtml({ self: false, sender: contactName, showAvatar: show, text: item.entry.prompt, stamp: syncClockFromOrd(ev.ord) });
        }
    }
    if (GS.contactSyncTyping === item.id) {
        out += syncTypingRow(contactName, false);
    }
    return out || '<div class="sync-empty">' + esc(CT('empty')) + '</div>';
}

function syncBaseThreadHtml(ch, revealed) {
    syncEnsureBaseOrders(revealed);
    const msgs = revealed.filter(function (m) { return m.ch === ch; });
    msgs.sort(function (a, b) {
        const d = syncBaseGord(a) - syncBaseGord(b);
        return d || (syncBaseOrdinal(a) - syncBaseOrdinal(b));
    });
    let prevSender = null;
    let out = '';
    for (let i = 0; i < msgs.length; i++) {
        const m = msgs[i];
        const self = !!m.self;
        const sender = self ? (GS.playerName || 'You') : (m.s || ch);
        const show = !self && sender !== prevSender;
        prevSender = self ? null : sender;
        out += syncRowHtml({ self: self, sender: sender, showAvatar: show, text: m.t, stamp: syncMessageStamp(syncBaseGord(m), m) });
    }
    if (GS.typing && GS.typing[ch]) out += syncTypingRow(GS.typing[ch], false);
    if (GS.selfTyping === ch) out += syncTypingRow(GS.playerName || 'You', true);
    return out || '<div class="sync-empty">—</div>';
}

// ---------------------------------------------------------------- sidebar items
function syncContactSidebarRows(items) {
    return items.map(function (item) {
        const c = item.contact;
        const pending = !repliedThisChapterSafe(item.id);
        const unread = pending;
        const preview = syncContactPreview(item);
        const active = GS.selCh === item.key ? ' active' : '';
        return '<div class="ch-item contact-ch' + active + (unread ? ' unread' : '') +
        '" onclick="switchChannel(\'' + esc(item.key) + '\')">' +
        avatarHtml(c.name && c.name.en, 'avatar-xs') +
        '<div class="ch-main"><div class="ch-name">' + esc(syncL(c.name)) + '</div>' +
        '<div class="ch-preview">' + esc(syncPreviewTrim(preview)) + '</div></div>' +
        (unread ? '<span class="ch-dot"></span>' : '') + '</div>';
    }).join('');
}
function syncBaseSidebarRows(channels, revealed) {
    return channels.map(function (ch) {
        const unread = !GS.seenChs.has(ch);
        const preview = syncChannelPreview(ch, revealed);
        const active = GS.selCh === ch ? ' active' : '';
        return '<div class="ch-item' + active + (unread ? ' unread' : '') +
        '" onclick="switchChannel(\'' + esc(ch) + '\')">' +
        avatarHtml(ch, 'avatar-xs') +
        '<div class="ch-main"><div class="ch-name">' + esc(ch) + '</div>' +
        '<div class="ch-preview">' + esc(syncPreviewTrim(preview)) + '</div></div>' +
        (unread ? '<span class="ch-dot"></span>' : '') + '</div>';
    }).join('');
}
function syncPreviewTrim(s) {
    s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
    return s.length > 64 ? s.slice(0, 62) + '…' : s;
}

// ---------------------------------------------------------------- main renderer
function syncScrollCaptureNow(c) {
    const msg = c.querySelector('.sync-msgs');
    const ch = c.querySelector('.sync-ch');
    let atBottom = true;
    if (msg) {
        atBottom = (msg.scrollHeight - msg.scrollTop - msg.clientHeight) <= 52;
        if (GS.selCh) GS.syncMsgScroll[GS.selCh] = msg.scrollTop;
    }
    if (ch) GS.syncListScroll = ch.scrollTop;
    return atBottom;
}
function syncScrollRestoreNow(c, atBottom) {
    const msg = c.querySelector('.sync-msgs');
    const ch = c.querySelector('.sync-ch');
    if (ch && typeof GS.syncListScroll === 'number') ch.scrollTop = GS.syncListScroll;
    if (!msg) return;
    let target = null;
    const grew = !!(GS.syncRenderCount && GS.syncRenderCount[GS.selCh] != null && GS._syncCountNow > GS.syncRenderCount[GS.selCh]);
    if (GS._syncForceBottom) target = msg.scrollHeight;
    else if (GS._syncJumpTo === GS.selCh) {
        target = (grew || GS.syncMsgScroll[GS.selCh] == null) ? msg.scrollHeight : GS.syncMsgScroll[GS.selCh];
    } else if (atBottom) target = msg.scrollHeight;
    else if (GS.selCh && GS.syncMsgScroll[GS.selCh] != null) target = GS.syncMsgScroll[GS.selCh];
    if (target == null) target = msg.scrollHeight;
    msg.scrollTop = target;
    if (GS.selCh) {
        GS.syncMsgScroll[GS.selCh] = msg.scrollTop;
        if (GS.syncRenderCount) GS.syncRenderCount[GS.selCh] = GS._syncCountNow;
    }
    GS._syncForceBottom = false;
    GS._syncJumpTo = null;
}

function renderSync() {
    const c = $('#c-sync');
    if (!c) return;
    syncEnsureState();
    // Defensive: never leave a stale "typing" indicator with no pending message.
    if (GS.typing) {
        Object.keys(GS.typing).forEach(function (ch) {
            const pending = (GS.chatPending || []).some(function (p) { return p.ch === ch; });
            if (!pending) delete GS.typing[ch];
        });
    }
    const revealed = syncSeenRevealed();
    const contactItems = (typeof syncOptionalChats === 'function') ? syncOptionalChats() : [];
    const channels = syncBaseChannels();
    const skipCapture = !!GS._syncSkipCapture;
    const atBottom = skipCapture ? false : syncScrollCaptureNow(c);
    GS._syncSkipCapture = false;
    if (GS.contactThreads) {
        for (const tid in GS.contactThreads) syncNormalizeThread(tid);
    }
    syncEnsureBaseOrders(revealed);

    const validChannels = contactItems.map(function (x) { return x.key; }).concat(channels);
    if (!GS.selCh || validChannels.indexOf(GS.selCh) < 0) {
        GS.selCh = contactItems.length ? contactItems[0].key : (channels[0] || null);
        if (GS.selCh && !csIsContactChannel(GS.selCh)) GS.seenChs.add(GS.selCh);
        GS._syncJumpTo = GS.selCh;
    }

    const contactSel = contactItems.filter(function (x) { return x.key === GS.selCh; })[0] || null;
    const baseSel = contactSel ? null : GS.selCh;

    let headHtml = '';
    let messagesHtml = '';
    let actionsHtml = '';

    if (contactSel) {
        const cObj = contactSel.contact;
        headHtml = '<div class="sync-head contact-head">' + avatarHtml(cObj.name && cObj.name.en, 'avatar-sm') +
        '<span class="sync-head-name">' + esc(syncL(cObj.name)) + '</span>' +
        (cObj.role ? '<span class="sync-head-role">' + esc(syncL(cObj.role)) + '</span>' : '') + '</div>';
        messagesHtml = syncContactThreadHtml(contactSel);
        const pending = !repliedThisChapterSafe(contactSel.id);
        const entry = contactSel.entry;
        const choices = syncEntryChoices(entry);
        if (pending && choices.length) {
            let acts = '<div class="sync-choice-title">' + esc(CT('choose')) + '</div>';
            for (let i = 0; i < choices.length; i++) {
                const reply = syncReplyForEntry(entry, choices[i], i);
                if (!reply) continue;
                acts += '<button class="btn wide sync-choice" onclick="contactSyncReply(\'' +
                esc(contactSel.id) + '\',' + i + ')">' + esc(syncL(choices[i].t)) + '</button>';
            }
            actionsHtml = acts;
        } else {
            actionsHtml = '<span class="no-act">' + esc(CT('done')) + '</span>';
        }
    } else if (baseSel) {
        const channelMsgs = revealed.filter(function (m) { return m.ch === baseSel; });
        channelMsgs.sort(function (a, b) { return syncBaseGord(a) - syncBaseGord(b); });
        headHtml = '<div class="sync-head">' + avatarHtml(baseSel, 'avatar-xs') +
        '<span class="sync-head-name">' + esc(baseSel) + '</span></div>';
        messagesHtml = syncBaseThreadHtml(baseSel, revealed);
        let unused = null;
        for (let i = channelMsgs.length - 1; i >= 0; i--) {
            const m = channelMsgs[i];
            if (m.act && !GS.usedActs.has(m.act.t)) { unused = m; break; }
        }
        actionsHtml = unused
        ? '<button class="btn wide" id="btn-s-' + esc(unused.act.t) + '" onclick="handleSyncAction(\'' + esc(unused.act.t) + '\',\'' + esc(baseSel) + '\')">' + esc(syncL(unused.act.l)) + '</button>'
        : '<span class="no-act">' + esc((typeof T !== 'undefined' && T[GS.lang] && T[GS.lang].noActions) || CT('noActions')) + '</span>';
    } else {
        messagesHtml = '<div class="sync-empty">—</div>';
        actionsHtml = '<span class="no-act">' + esc((typeof T !== 'undefined' && T[GS.lang] && T[GS.lang].noActions) || CT('noActions')) + '</span>';
    }

    const contactRows = syncContactSidebarRows(contactItems);
    const baseRows = syncBaseSidebarRows(channels, revealed);
    const listHead = GS.lang === 'zh' ? '信息' : 'Messages';
    const groupContacts = GS.lang === 'zh' ? '联系人' : 'Contacts';
    const groupChannels = GS.lang === 'zh' ? '频道' : 'Channels';

    c.innerHTML =
    '<div class="sync-layout"><div class="sync-split">' +
    '<div class="sync-ch"><div class="sync-ch-head">' + esc(listHead) + '</div>' +
    (contactRows ? '<div class="sync-ch-group">' + esc(groupContacts) + '</div>' + contactRows : '') +
    (baseRows ? '<div class="sync-ch-group">' + esc(groupChannels) + '</div>' + baseRows : '') +
    '</div>' +
    '<div class="sync-main">' + headHtml +
    '<div class="sync-msgs">' + messagesHtml + '</div>' +
    '<div class="sync-act">' + actionsHtml + '</div></div>' +
    '</div></div>';

    GS._syncCountNow = (contactSel ? syncContactEvents(contactSel).events.length : (baseSel ? revealed.filter(function (m) { return m.ch === baseSel; }).length : 0));
    syncScrollRestoreNow(c, atBottom);
}

// ---------------------------------------------------------------- channel switching
function switchChannel(ch) {
    syncEnsureState();
    const c = $('#c-sync');
    if (c) {
        const listBox = c.querySelector('.sync-ch');
        if (listBox) GS.syncListScroll = listBox.scrollTop;
        if (GS.selCh) {
            const msg = c.querySelector('.sync-msgs');
            if (msg) GS.syncMsgScroll[GS.selCh] = msg.scrollTop;
        }
    }
    GS.selCh = ch;
    GS._syncJumpTo = ch;
    GS._syncSkipCapture = true;
    if (csIsContactChannel(ch)) {
        const id = csContactIdFromChannel(ch);
        markContactSeenSync(id);
        const item = (typeof syncOptionalItemFor === 'function') ? syncOptionalItemFor(id) : null;
        if (item) { /* optional chat exists */ }
    } else if (ch) {
        GS.seenChs.add(ch);
    }
    renderSync();
    if (typeof updateDots === 'function') appSafe(function () { updateDots(); }, null);
    if (typeof refreshUnread === 'function') appSafe(function () { refreshUnread(); }, null);
}

// ---------------------------------------------------------------- replies
function contactSyncReply(id, idx) {
    syncEnsureState();
    const item = syncOptionalItemFor(id);
    if (!item) return;
    const entry = item.entry;
    const choices = syncEntryChoices(entry);
    const choice = choices[idx];
    if (!choice) return;
    const reply = syncReplyForEntry(entry, choice, idx);
    if (!reply) return;
    if (repliedThisChapterSafe(id)) return;

    const th = syncThreadOf(id);
    const promptGord = syncPromptGord(id);
    let hasPromptThisChapter = false;
    for (let i = 0; i < th.length; i++) {
        if (th[i] && th[i].ch === GS.ch && th[i].from === 'them' && th[i].prompt) { hasPromptThisChapter = true; break; }
    }
    if (!hasPromptThisChapter) {
        syncPushThread(id, { ch: GS.ch, from: 'them', text: syncL(entry.prompt), prompt: true, ord: promptGord, gord: promptGord, stamp: syncClockFromOrd(promptGord) });
    }
    const youGord = syncNextGlobal();
    syncPushThread(id, { ch: GS.ch, from: 'you', text: syncL(choice.t), ord: youGord, gord: youGord, stamp: syncClockFromOrd(youGord) });
    if (typeof affinityOf === 'function' && typeof choice.d === 'number' && GS.affinity) {
        try {
            const aff = affinityOf(id) + choice.d;
            GS.affinity[id] = Math.max(0, Math.min(100, aff));
        } catch (e) { }
    }
    GS.contactDone[GS.ch] = true;
    markContactSeenSync(id);
    const wasAtBottom = (function () {
        const c = $('#c-sync');
        const m = c && c.querySelector('.sync-msgs');
        if (!m) return true;
        return (m.scrollHeight - m.scrollTop - m.clientHeight) <= 52;
    })();
    if (GS.selCh === csChannelKey(id)) GS._syncForceBottom = wasAtBottom;
    GS.contactSyncTyping = id;
    if (typeof playSfx === 'function') appPlay('message');
    renderSync();
    if (typeof updateDots === 'function') appSafe(function () { updateDots(); }, null);

    const atChapter = GS.ch;
    const threadRef = th;
    const timer = setTimeout(function () {
        if (!GS.contactThreads || GS.contactThreads[id] !== threadRef) {
            if (GS.contactSyncTyping === id) GS.contactSyncTyping = null;
            return;
        }
        const replyGord = syncNextGlobal();
        threadRef.push({ ch: atChapter, from: 'them', text: syncL(reply), ord: replyGord, gord: replyGord, stamp: syncClockFromOrd(replyGord) });
        if (GS.contactSyncTyping === id) GS.contactSyncTyping = null;
        if (GS.ch === atChapter && GS.selCh === csChannelKey(id)) {
            GS._syncForceBottom = wasAtBottom;
            renderSync();
        }
        if (typeof updateDots === 'function') appSafe(function () { updateDots(); }, null);
    }, 10000 + Math.random() * 5000);
    GS.syncTimers.push(timer);
}

// ---------------------------------------------------------------- Contacts app bridge
// Only optional chats are exposed to the Contacts app; mainline contacts keep
// their scripted channel and show no extra message button.
function chatEntryFor(cid) {
    if (typeof syncOptionalEntryFor !== 'function') return null;
    return syncOptionalEntryFor(cid);
}
function contactHasMessageButton(c) {
    if (!c || c.type === 'ai' || c.noChat) return false;
    const entry = (typeof syncOptionalEntryFor === 'function') ? syncOptionalEntryFor(c.id) : null;
    if (entry) return !repliedThisChapterSafe(c.id);
    // Mainline DM: the row button should still open the conversation.
    return !!(typeof csBaseChannelForContact === 'function' && csBaseChannelForContact(c));
}
function contactHasPendingConversation(id) {
    const c = (typeof contactById === 'function') ? contactById(id) : null;
    if (!c) return false;
    const entry = (typeof syncOptionalEntryFor === 'function') ? syncOptionalEntryFor(c.id) : null;
    return !!(entry && !repliedThisChapterSafe(c.id));
}
function openContactSync(id) {
    ensureContactSyncState();
    const c = (typeof contactById === 'function') ? contactById(id) : null;
    if (!c) return;
    markContactSeenSync(id);
    const entry = (typeof syncOptionalEntryFor === 'function') ? syncOptionalEntryFor(c.id) : null;
    if (entry) GS.selCh = csChannelKey(id);
    else {
        const base = (typeof csBaseChannelForContact === 'function') ? csBaseChannelForContact(c) : null;
        if (!base) { if (typeof toast === 'function') toast(CT('openFailed'), 'warn'); return; }
        GS.selCh = base;
    }
    if (typeof openWindow === 'function') {
        openWindow('sync');
        return;
    }
    renderSync();
    if (typeof updateDots === 'function') appSafe(() => updateDots(), null);
}

// ---------------------------------------------------------------- boot
syncEnsureState();
// ============================================================================
//  DRAWN TRAVEL TRANSITION — station dots + animated route (SVG, no assets)
// ============================================================================
function showTravelAnimation(cfg) {
    return new Promise((resolve) => {
        const isFlight = cfg.mode === 'flight';
        const from = L(travelCity(cfg.from));
        const to = L(travelCity(cfg.to));
        const modeLabel = isFlight ? T[GS.lang].bookModeFlight
            : (cfg.mode === 'local' ? T[GS.lang].bookModeLocal : T[GS.lang].bookModeTrain);
        const ov = document.createElement('div');
        ov.className = 'travel-overlay-2';
        const p1 = isFlight ? 'M 150 250 Q 400 40 650 250' : 'M 150 250 L 650 250';
        const p2 = isFlight ? 'M 650 250 Q 900 40 1150 250' : 'M 650 250 L 1150 250';
        ov.innerHTML =
            '<div class="tv2-card">' +
            '<div class="tv2-kicker">' + esc(GS.lang === 'zh' ? '旅程' : 'IN TRANSIT') + ' · ' + esc(fmtMailDate(cfg.date)) + '</div>' +
            '<div class="tv2-title">' + esc(from) + ' <span>→</span> ' + esc(to) + '</div>' +
            '<svg class="tv2-map" viewBox="0 0 1300 360" preserveAspectRatio="xMidYMid meet">' +
            '<path class="tv2-route-bg" d="' + p1 + ' ' + p2 + '"/>' +
            '<path class="tv2-route" id="tv2-route" d="' + p1 + ' ' + p2 + '"/>' +
            '<circle class="tv2-node" cx="150" cy="250" r="9"/><circle class="tv2-node" cx="650" cy="250" r="5" opacity=".55"/><circle class="tv2-node" cx="1150" cy="250" r="9"/>' +
            '<text class="tv2-label" x="150" y="292" text-anchor="middle">' + esc(from) + '</text>' +
            '<text class="tv2-label end" x="1150" y="292" text-anchor="middle">' + esc(to) + '</text>' +
            '<text class="tv2-mode" x="650" y="200" text-anchor="middle">' + (isFlight ? '✈' : '🚆') + ' ' + esc(modeLabel) + '</text>' +
            '</svg>' +
            '<div class="tv2-meta">' + esc(cfg.depart) + ' → ' + esc(cfg.arrive) + ' · ' + esc(L(cfg.operator || { en: '', zh: '' })) + '</div>' +
            '</div>';
        document.body.appendChild(ov);
        requestAnimationFrame(() => {
            const path = ov.querySelector('#tv2-route');
            if (path) {
                const len = path.getTotalLength ? path.getTotalLength() : 1200;
                path.style.strokeDasharray = len;
                path.style.strokeDashoffset = len;
                path.getBoundingClientRect();
                path.style.transition = 'stroke-dashoffset 4300ms cubic-bezier(.4,0,.2,1)';
                path.style.strokeDashoffset = '0';
            }
        });
        setTimeout(() => { resolve(ov); }, 5000);
    });
}

