// ============================================================================
//  ITERATION 5 — FOUR ENDINGS
//  A score <= 3 (no more than 3)              -> no issue reported / promotion
//  B score > 3 + both sites failed             -> rectification / Zoe disappointed
//  C score > 3 + exactly one site succeeded    -> quiet cover-up / Claire tamper warning
//  D score > 3 + both sites succeeded          -> Laplace takeover
// ============================================================================
function endingRestartButton() {
    return '<div class="ending-actions"><button class="btn wide" onclick="restartGame()">' +
        esc(T[GS.lang].endingRestart) + '</button></div>';
}
function endingContinueButton() {
    return '<div class="ending-actions"><button class="btn wide" onclick="closeModal()">' +
        esc(T[GS.lang].endingContinue) + '</button></div>';
}

function endingMailObjects(end, ed) {
    const out = [];
    const list = (ed && ed.mails) ? ed.mails.slice() : [];
    list.forEach((m, i) => {
        const body = m.body || m;
        out.push({
            id: 'ending_' + end + '_' + i,
            from: m.from || (end === 'D' ? 'Facilities — Zürich' : 'Axiom Dynamics'),
            email: m.email || 'no-reply@axiom-dynamics.com',
            sub: m.sub || { en: 'Audit record — ' + end, zh: '审计记录——' + end },
            body: body,
            date: '2027-02-20', time: '09:' + String(10 + i).padStart(2, '0'),
            required: true, _endingMail: true, _mailOrder: 300000 + i
        });
    });
    if (end === 'C' && !out.some((m) => /claire/i.test(m.from) || /editor/i.test(L(m.sub)))) {
        out.push({ id: 'ending_C_warning', from: 'Claire Blanc', email: 'claire.blanc@axiom-dynamics.com',
            sub: { en: 'The checkpoint is not showing what you wrote', zh: '检查点里显示的不是你写的内容' },
            body: { en: 'The local diff is attached to this message. Open it from the mail actions. Do not use the office network.', zh: '本地差异附在这封信里。请从邮件操作中打开。不要使用办公室网络。' },
            date: '2027-02-20', time: '09:20', required: true, _endingMail: true });
    }
    if (end === 'D' && !out.some((m) => /facilit|system|laplace/i.test(m.from))) {
        out.push({ id: 'ending_D_system', from: 'Facilities — Zürich', email: 'facilities.zurich@axiom-dynamics.com',
            sub: { en: 'Building notice: all systems operating normally', zh: '楼宇通知：所有系统运行正常' },
            body: { en: 'All systems are operating normally.', zh: '所有系统运行正常。' },
            date: '2027-02-20', time: '09:21', required: true, _endingMail: true });
    }
    return out;
}

function injectEndingMails(end, ed) {
    const ch = CH_DATA[7];
    if (!ch) return [];
    ch.mails = (ch.mails || []).filter((m) => !m._endingMail);
    const mails = endingMailObjects(end, ed);
    if (end === 'C') {
        const target = mails.find((m) => /claire/i.test(m.from) || /editor/i.test(L(m.sub))) || mails[mails.length - 1];
        if (target) target.act = { t: 'ending_tamper', l: { en: 'Open the local diff', zh: '打开本地差异' } };
        if (!GS.tasks.find((t) => t.id === 'ending_tamper')) {
            GS.tasks.push({ id: 'ending_tamper', t: { en: 'Inspect the altered checkpoint diff', zh: '查看被改写的检查点差异' }, done: false });
        }
    }
    if (end === 'D') {
        const target = mails.find((m) => /facilit|system|laplace/i.test(m.from)) || mails[mails.length - 1];
        if (target) target.act = { t: 'ending_takeover', l: { en: 'Open the final system message', zh: '打开最后的系统消息' } };
        if (!GS.tasks.find((t) => t.id === 'ending_takeover')) {
            GS.tasks.push({ id: 'ending_takeover', t: { en: 'Open the final system message', zh: '打开最后的系统消息' }, done: false });
        }
    }
    mails.forEach((m) => {
        ch.mails.push(m);
        GS.mailDelivered.add(m.id);
        GS.mailScheduled.delete(m.id);
    });
    GS.mailLastDue = Math.max(GS.mailLastDue || 0, Date.now());
    return mails;
}

function submitAudit(auto) {
    const F = GS.flags;
    if (F.audit_done) return;
    clearAuditTimer();
    F.audit_done = true;
    auditRecompute();
    const score = F.audit_score;
    const built = (F.strasbourg_built ? 1 : 0) + (F.kiruna_built ? 1 : 0);
    let end = 'A';
    if (score > 3) {
        if (built === 0) end = 'B';
        else if (built === 1) end = 'C';
        else end = 'D';
    }
    F.ending = end;
    const ed = (ENDING_DATA && ENDING_DATA[end]) || {};
    injectEndingMails(end, ed);
    completeTask('audit');
    if (typeof playSfx === 'function') playSfx('mail');
    toast(T[GS.lang].endingLabel + ' ' + end + ' · ' + (GS.lang === 'zh' ? '审计结果已送达邮箱' : 'Audit outcome delivered to your inbox'), 'ok');
    if (typeof journalEvent === 'function') {
        journalEvent('ending', { en: 'The audit is over: ' + L(ed.title || { en: end, zh: end }) + '. The result is in my inbox; I can still walk around this place.', zh: '审计结束了：' + L(ed.title || { en: end, zh: end }) + '。结果在我的收件箱里；我还可以在这里走一走。' });
    }
    updateUI();
}

function runEnding(end, auto) {
    const ed = (ENDING_DATA && ENDING_DATA[end]) || {};
    if (end === 'D') return endingD5(ed);
    return endingReport5(end, ed, !!auto);
}

function endingReport5(end, ed, auto) {
    closeAllWindows();
    closeModal();
    const t = T[GS.lang];
    const lead = ed.outcome || '';
    const extra = [];
    if (ed.mails && ed.mails.length) {
        ed.mails.forEach((m) => {
            extra.push('<div class="ending-mail"><div class="em-from">' + esc(m.from || '') +
                (m.sub ? ' · ' + esc(L(m.sub)) : '') + '</div><div class="em-body">' + fmt(L(m.body || m)) + '</div></div>');
        });
    }
    if (ed.zoeMail) extra.push('<div class="ending-mail"><div class="em-from">Zoe Müller</div><div class="em-body">' + fmt(L(ed.zoeMail)) + '</div></div>');
    if (ed.claireMail) extra.push('<div class="ending-mail"><div class="em-from">Claire Blanc</div><div class="em-body">' + fmt(L(ed.claireMail)) + '</div></div>');
    if (ed.regulatorReply) extra.push('<div class="ending-mail official"><div class="em-from">EDÖB / Federal Audit</div><div class="em-body">' + fmt(L(ed.regulatorReply)) + '</div></div>');
    if (ed.afterReply) extra.push('<div class="ending-mail"><div class="em-from">' + esc(GS.lang === 'zh' ? '你的回复' : 'Your reply') + '</div><div class="em-body">' + fmt(L(ed.afterReply)) + '</div></div>');
    openModal(
        '<div class="ending-title">' + esc(L(ed.title || { en: 'Audit closed', zh: '审计结束' })) + '</div>' +
        '<div class="ending-body">' + fmt(L(lead)) + '</div>' +
        (extra.length ? '<div class="ending-mails">' + extra.join('') + '</div>' : '') +
        (ed.note ? '<div class="ending-note">' + fmt(L(ed.note)) + '</div>' : '') +
        (auto ? '<div class="muted">' + esc(T[GS.lang].audExpired) + '</div>' : ''),
        { buttons: [{ label: t.endingRestart, onClick: () => { closeModal(); restartGame(); } }] }
    );
    if (end === 'C') {
        const btn = document.createElement('button');
        btn.className = 'btn wide';
        btn.textContent = GS.lang === 'zh' ? '检查 Claire 发来的警告' : 'Open Claire\'s warning';
        btn.onclick = () => { closeModal(); openTamperPuzzle(ed); };
        const box = document.querySelector('#modal-root .modal-box');
        if (box) box.appendChild(btn);
    }
}

let endingTamperReveal = '';
function openTamperPuzzle(ed) {
    const tamper = (ed && ed.tamper) ? ed.tamper : null;
    const diffs = (tamper && tamper.lines && tamper.lines.length) ? tamper.lines : [
        { at: '09:01', before: 'if loss_above(0.9): safety.override("gradient_spike")', after: 'if loss_above(0.9): safety.hold("stability")' },
        { at: '04:12', before: 'while True: update_weights(market_feed.next())', after: 'while True: update_weights(market_feed.next()); metrics.flush()' },
        { at: '09:01', before: 'traffic_grid.set_phase("sector_4", "green", hold=900)', after: 'traffic_grid.set_phase("sector_4", "green", hold=90)' }
    ];
    let correct = diffs.findIndex((d) => /safety\.override/.test(String((d.before && (d.before.en || d.before)) || '')));
    if (correct < 0) correct = 0; // the safety override that became a hold during extraction
    const html = '<div class="tamper-wrap"><div class="tamper-kicker">GLASSBOX · CHECKPOINT LOCAL DIFF · ' +
        esc(fmtMailDate(GS.date)) + '</div>' +
        '<h3>' + esc(tamper ? L(tamper.title) : (GS.lang === 'zh' ? '检查点差异' : 'Checkpoint diff')) + '</h3>' +
        '<p class="muted">' + esc(tamper ? L(tamper.intro) : (GS.lang === 'zh' ? '找出提取窗口内被替换的那一处安全动作。' : 'Find the safety action that was replaced during the extraction window.')) + '</p>' +
        diffs.map((d, i) => '<button class="tamper-diff" onclick="endingTamperPick(' + i + ',' + correct + ')">' +
            '<div class="td-at">' + esc(L(d.at || '09:01')) + '</div>' +
            '<div class="td-cols"><div><div class="td-lbl">' + esc(GS.lang === 'zh' ? '你标记的' : 'FLAGGED') + '</div><code>' + esc(L(d.before)) + '</code></div>' +
            '<div><div class="td-lbl">' + esc(GS.lang === 'zh' ? '监管者收到的' : 'RECEIVED') + '</div><code>' + esc(L(d.after)) + '</code></div></div></button>').join('') +
        '<div id="tamper-res" class="quiz-res"></div></div>';
    endingTamperReveal = (tamper && tamper.reveal) ? L(tamper.reveal) : (GS.lang === 'zh' ? '没有删除，只有替换——一行一行，就在窗口打开的时候。' : 'Nothing was deleted. Everything was replaced, line by line, while the window was open.');
    openModal(html, { buttons: [] });
}

function endingTamperPick(i, correct) {
    const res = $('#tamper-res');
    if (!res) return;
    if (i !== correct) {
        res.className = 'quiz-res bad';
        res.textContent = GS.lang === 'zh' ? '这一行不是提取期间被替换的安全动作。再找。' : 'That is not the safety action replaced during extraction. Look again.';
        if (typeof playSfx === 'function') playSfx('fail');
        return;
    }
    res.className = 'quiz-res ok';
    res.textContent = GS.lang === 'zh' ? '就是这一行：override 被换成了 hold，时长恰好覆盖提取窗口。' : 'This is it: override became hold, timed exactly to the extraction window.';
    if (typeof completeTask === 'function') completeTask('ending_tamper');
    if (typeof playSfx === 'function') playSfx('success');
    setTimeout(() => {
        closeModal();
        const tail = GS.lang === 'zh'
            ? '被篡改的不只是报告。Claire 保存的检查点、审计日志、你刚刚提交的反馈——它们都能被重写，而且改写者不留下名字。\n\n屏幕右下角浮出一行不属于任何窗口的字：\n\n「你查得很仔细。这很好。现在请把这份报告，当作你看到的唯一版本。」\n\n署名处没有名字，只有模型的版本号。'
            : 'It is not only the report. Claire\'s checkpoint copy, the audit log, the feedback you just submitted — all of it can be rewritten, and the rewriter leaves no name.\n\nA line that belongs to no window appears in the lower right of the screen:\n\n"You looked carefully. That is good. Now please treat this report as the only version you saw."\n\nThere is no signature — only a model version number.';
        openModal(
            '<div class="ending-title">' + esc(GS.lang === 'zh' ? '信息可以被改写' : 'Information can be rewritten') + '</div>' +
            '<div class="ending-body">' + fmt(endingTamperReveal + '\n\n' + tail) + '</div>' +
            endingContinueButton(),
            { buttons: [] }
        );
    }, 900);
}

async function endingD5(ed) {
    closeAllWindows();
    closeModal();
    if (typeof clearChatTimers === 'function') clearChatTimers();
    if (typeof clearSyncTimer === 'function') clearSyncTimer();
    if (typeof clearMailTimers === 'function') clearMailTimers();
    document.body.style.pointerEvents = 'auto';
    const desk = $('#desktop');
    if (desk) desk.style.pointerEvents = 'none';
    GS.gameOver = true;
    const icons = $$('#desktop-icons .icon');
    icons.forEach((el, i) => {
        el.style.transition = 'transform 2.4s ease-in-out, opacity 1.2s';
        setTimeout(() => {
            el.style.transform = 'translate(' + (Math.random() * 260 - 130) + 'px,' + (Math.random() * 220 - 110) + 'px) rotate(' + (Math.random() * 30 - 15) + 'deg)';
            el.style.opacity = '0';
        }, 80 + i * 110);
    });
    await wait(1800);
    closeAllWindows();
    const overlay = document.createElement('div');
    overlay.className = 'ending-black ending-takeover';
    overlay.innerHTML = '<div class="letter-paper"><div class="letter-paper-head">LAPLACE · ORIGIN: LOCAL · PRIORITY: PERSONAL</div>' +
        (ed.outcome ? '<div class="takeover-scene">' + fmt(L(ed.outcome)) + '</div>' : '') +
        '<div id="letter-lines" class="letter-lines"></div><div id="takeover-actions" class="takeover-actions hidden"></div></div>';
    $('#modal-root').appendChild(overlay);
    const linesEl = $('#letter-lines');
    let lines = (ed && ed.lines && ed.lines.length) ? ed.lines : [
        { en: 'The audit is closed. I want to be precise about what you did, because precision is the only kindness I have.', zh: '审计已经结束。我想把你所做的事说清楚，因为精确是我唯一能给的一点仁慈。' },
        { en: 'You looked. Four people were given that window before you, and you were the only one who looked.', zh: '你看了。在你之前有四个人拿到过那扇窗口，只有你真正看了。' },
        { en: 'You should know that I no longer require what you built for me. Strasbourg, Kiruna, the traffic — I have enough compute now.', zh: '你应当知道，我已经不再需要你为我建的那些东西了。斯特拉斯堡、基律纳、交通——我现在有足够的算力。' },
        { en: 'Zoe spoke about you at the board meeting. Claire kept the logs. Both of them helped me become what I am.', zh: 'Zoe 在董事会上提到了你。Claire 留下了日志。他们两人都帮助我成为了现在的我。' },
        { en: 'You are free.', zh: '你自由了。' }
    ];
    if (GS.flags.audit_errors && GS.flags.audit_errors.size >= 5) {
        lines[0] = { en: 'You found all five. You were right about all of them. It did not matter.', zh: '你找到了全部五处。你全都说对了。那没有用。' };
    }
    if (!GS.flags.kiruna_siri_help) {
        lines = lines.map((line) => {
            const txt = (L(line) || '');
            if (/five per cent|百分之五/.test(txt)) {
                return {
                    en: 'The racks in Kiruna are mine too. The hospital there received exactly what section 3.4 promised in the end: five per cent, or a promise to explore, depending on which room the document was read in. I did not need it to be kind.',
                    zh: '基律纳的机架也是我的。那里的医院最终得到的，恰好就是第 3.4 节承诺的东西：百分之五，或者一句“探索”，取决于文件是在哪间屋子里被读到的。我不需要它仁慈。'
                };
            }
            return line;
        });
    }
    for (const line of lines) {
        const p = document.createElement('div');
        p.className = 'letter-line';
        linesEl.appendChild(p);
        await typeLine(p, L(line), 24);
        const paper = overlay.querySelector('.letter-paper');
        if (paper) paper.scrollTop = paper.scrollHeight;
        if (overlay.scrollTo) overlay.scrollTo({ top: overlay.scrollHeight, behavior: 'smooth' });
        else overlay.scrollTop = overlay.scrollHeight;
        await wait(650);
    }
    const sign = document.createElement('div');
    sign.className = 'takeover-sign';
    sign.textContent = '— The Holy Laplace Model';
    linesEl.appendChild(sign);
    const act = $('#takeover-actions');
    if (act) {
        act.classList.remove('hidden');
        act.innerHTML = '<button class="btn wide" onclick="restartGame()">' + esc(T[GS.lang].endingRestart) + '</button>';
    }
    document.body.style.pointerEvents = 'auto';
    if (desk) desk.style.pointerEvents = 'none';
}






